css:
@media (prefers-reduced-motion:reduce){.mt{display:none} }
.nm{display:none}@media (prefers-reduced-motion:reduce){.nm{display:inline} }
.pls{animation:pls 2.4s ease-in-out infinite}@keyframes pls{50%{opacity:.35} }
.fl{animation:fl 1.4s linear infinite}@keyframes fl{to{stroke-dashoffset:-28} }
.tw1{animation:tw 3.1s ease-in-out infinite}.tw2{animation:tw 4.3s ease-in-out infinite}.tw3{animation:tw 5.7s ease-in-out infinite}@keyframes tw{50%{opacity:.25} }
.bk1{animation:bk 1.7s steps(1) infinite}.bk2{animation:bk 2.3s steps(1) infinite}.bk3{animation:bk 3.1s steps(1) infinite}.bk4{animation:bk 1.1s steps(1) infinite}@keyframes bk{50%{opacity:.15} }
.cur{animation:cur 1.1s steps(1) infinite}@keyframes cur{50%{opacity:0} }
@media (prefers-reduced-motion:reduce){.fl,.pls,.tw1,.tw2,.tw3,.bk1,.bk2,.bk3,.bk4,.cur{animation:none} }
